import { buildExcelReport } from '@lib/export/excel-report'
import { garageUnitLabel } from './fuel-units'
import type { GarageReportResult } from './reports'
import { parentSectorLabel } from '@sdk/sectors.sdk'

const fuelLabels:Record<string,string>={gas_oil:'الكاز',hydraulic:'الهيدروليك',grease:'الدهن',c_oil:'C-Oil'}
const movementLabels:Record<string,string>={stock_in:'إضافة مخزون',vehicle_fill:'تعبئة آلية',approved_reset:'تصفير معتمد'}
const arDate=(value:string)=>new Intl.DateTimeFormat('ar-IQ-u-nu-latn',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Baghdad'}).format(new Date(value))
const reportIdentity=(result:GarageReportResult)=>{const selected=result.selectedVehicles??[],first=selected.at(0);return first&&selected.length===1?{title:`تقرير الآلية ${first.vehicleName} · DB ${first.dbNumber}`,slug:`الية-${first.dbNumber}`,detail:`السائق: ${first.driverName} · اللوحة: ${first.plateNumber} · المنطقة: ${first.areaName??'—'}`} : selected.length>1?{title:`تقرير ${selected.length} آليات محددة`,slug:`اليات-محددة-${selected.length}`,detail:selected.map(v=>`${v.vehicleName} · DB ${v.dbNumber}`).join('، ')}:{title:'تقرير الوقود والمخزون',slug:'الكراج',detail:'جميع الآليات والخزانات'} }
export function exportGarageCsv(result:GarageReportResult):void{
  const safe=(value:unknown)=>{let text=String(value??'');if(/^[=+\-@]/.test(text))text=`'${text}`;return `"${text.replaceAll('"','""')}"`}
  const headers=['نوع الحركة','المادة','الخزان','الآلية','DB','المنطقة','الكمية','الوحدة','الرصيد قبل','الرصيد بعد','الموعد التالي','وقت العملية','منفذ العملية','ملاحظات']
  const lines=[headers,...result.rows.map(row=>[movementLabels[row.movementType],fuelLabels[row.fuelType],row.tankName,row.vehicleName??'',row.dbNumber??'',row.areaName??'',Math.abs(row.quantity),garageUnitLabel(row.unit),row.quantityBefore,row.quantityAfter,row.fuelType==='gas_oil'?'لا ينطبق':(row.nextRefillDate??''),arDate(row.createdAt),row.actorName,row.notes??''])].map(row=>row.map(safe).join(','))
  if(typeof document==='undefined'||typeof URL?.createObjectURL!=='function')return
  const url=URL.createObjectURL(new Blob([`\ufeff${lines.join('\n')}`],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`تقرير-${reportIdentity(result).slug}-${result.from}-${result.to}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000)
}
const htmlEscape=(value:unknown)=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]??char))
export function printGarageReport(result:GarageReportResult,preparedWindow?:Window|null):void{
  if(typeof window==='undefined')return
  const popup=preparedWindow??window.open('','_blank','width=1200,height=850')
  if(!popup)throw new Error('تعذر فتح نافذة الطباعة. اسمح بالنوافذ المنبثقة ثم أعد المحاولة.')
  popup.opener=null
  popup.document.open()
  const identity=reportIdentity(result)
  const maxType=Math.max(1,...result.byType.map(item=>item.quantity));const maxTank=Math.max(1,...result.byTank.map(item=>item.consumption))
  const bars=(items:Array<{label:string;value:number;unit:string}>,max:number)=>items.map(item=>`<div class="bar"><b>${htmlEscape(item.label)}</b><div class="track"><i style="width:${Math.max(item.value?4:0,item.value/max*100)}%"></i></div><span>${htmlEscape(item.value)} ${htmlEscape(item.unit)}</span></div>`).join('')||'<p class="empty">لا توجد بيانات</p>'
  popup.document.write(`<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>تقرير الكراج المركزي</title><style>@page{size:A4 landscape;margin:9mm}*{box-sizing:border-box}body{margin:0;background:#eaf4f8;color:#102235;font-family:Tahoma,Arial,sans-serif}.sheet{max-width:1200px;margin:auto;background:#fff;padding:24px}.brand{display:flex;align-items:center;gap:16px;border-bottom:4px solid #087f8c;padding-bottom:14px}.brand img{width:64px;height:64px;object-fit:contain}.brand h1{margin:0;font-size:24px}.brand p{margin:6px 0 0;color:#547083}.period{margin-right:auto;text-align:left;font-size:12px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0}.card{border:1px solid #d7e4eb;border-radius:15px;padding:13px;background:#f8fbfc}.card b{display:block;margin-top:6px;font-size:21px;color:#075985}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.box{border:1px solid #d7e4eb;border-radius:16px;padding:15px}.box h2{margin:0 0 14px;font-size:15px;border-right:4px solid #0e9aaa;padding-right:8px}.bar{display:grid;grid-template-columns:120px 1fr 105px;align-items:center;gap:8px;margin:9px 0;font-size:11px}.track{height:12px;border-radius:99px;background:#e7eff3;overflow:hidden}.track i{display:block;height:100%;background:linear-gradient(90deg,#0e9aaa,#075985)}table{width:100%;border-collapse:collapse;margin-top:18px;font-size:9px}thead{display:table-header-group}th{background:#083344;color:#fff}th,td{border:1px solid #d8e2e8;padding:6px;text-align:right}tbody tr:nth-child(even){background:#f4f8fa}tr{break-inside:avoid}.footer{margin-top:15px;border-top:1px solid #d7e4eb;padding-top:10px;color:#64748b;font-size:10px}.empty{color:#94a3b8}@media print{body{background:white}.sheet{padding:0}.grid,.box,.card{break-inside:avoid}}@media(max-width:750px){.cards,.grid{grid-template-columns:1fr 1fr}.period{display:none}}</style></head><body><main class="sheet"><header class="brand"><img src="${location.origin}${import.meta.env.BASE_URL}icons/logo.png" alt="شعار شركة جزيرة الأكارم"><div><h1>شركة جزيرة الأكارم</h1><p>بوابة الكراج المركزي · ${htmlEscape(identity.title)}</p><small>${htmlEscape(identity.detail)}</small></div><div class="period"><b>الفترة</b><br>${htmlEscape(result.from)} — ${htmlEscape(result.to)}<br>${new Date().toLocaleString('ar-IQ-u-nu-latn',{timeZone:'Asia/Baghdad'})}</div></header><section class="cards"><div class="card">عدد الحركات<b>${result.totalCount}</b></div>${result.byUnit.map(item=>`<div class="card">استهلاك ${htmlEscape(garageUnitLabel(item.unit))}<b>${htmlEscape(item.consumption)}</b><small>إضافات ${htmlEscape(item.stockIn)} · تصفير ${htmlEscape(item.reset)}</small></div>`).join('')}</section><section class="grid"><div class="box"><h2>الاستهلاك حسب المادة</h2>${bars(result.byType.map(item=>({label:fuelLabels[item.fuelType]??item.fuelType,value:item.quantity,unit:garageUnitLabel(item.unit)})),maxType)}</div><div class="box"><h2>الاستهلاك حسب الخزان</h2>${bars(result.byTank.map(item=>({label:item.tankName,value:item.consumption,unit:garageUnitLabel(item.unit)})),maxTank)}</div></section><table><thead><tr><th>#</th><th>الوقت</th><th>الحركة</th><th>المادة</th><th>الخزان</th><th>الآلية</th><th>DB</th><th>الكمية</th><th>قبل / بعد</th><th>الموعد التالي</th><th>المنفذ</th></tr></thead><tbody>${result.rows.map((row,index)=>`<tr><td>${index+1}</td><td>${htmlEscape(arDate(row.createdAt))}</td><td>${htmlEscape(movementLabels[row.movementType])}</td><td>${htmlEscape(fuelLabels[row.fuelType])}</td><td>${htmlEscape(row.tankName)}</td><td>${htmlEscape(row.vehicleName??'—')}</td><td>${htmlEscape(row.dbNumber??'—')}</td><td>${htmlEscape(Math.abs(row.quantity))} ${htmlEscape(garageUnitLabel(row.unit))}</td><td>${htmlEscape(row.quantityBefore)} ← ${htmlEscape(row.quantityAfter)}</td><td>${row.fuelType==='gas_oil'?'لا ينطبق':htmlEscape(row.nextRefillDate??'—')}</td><td>${htmlEscape(row.actorName)}</td></tr>`).join('')}</tbody></table><footer class="footer">تقرير إلكتروني صادر من نظام شركة جزيرة الأكارم · جميع الأوقات محسوبة بتوقيت بغداد</footer></main><script>addEventListener('load',()=>setTimeout(()=>print(),300))</script></body></html>`)
  popup.document.close()
}

export async function exportGarageReport(result:GarageReportResult):Promise<void>{
  const identity=reportIdentity(result)
  const unitSummary=result.byUnit.map(item=>`${garageUnitLabel(item.unit)}: إضافة ${item.stockIn}، استهلاك ${item.consumption}، تصفير ${item.reset}`).join(' | ')
  const charts=result.byUnit.flatMap(({unit})=>[
    {title:`الاستهلاك حسب المادة — ${garageUnitLabel(unit)}`,kind:'bar' as const,valueLabel:garageUnitLabel(unit),data:result.byType.filter(item=>item.unit===unit).map(item=>({label:fuelLabels[item.fuelType]??item.fuelType,value:item.quantity}))},
    {title:`الاستهلاك حسب الخزان — ${garageUnitLabel(unit)}`,kind:'bar' as const,valueLabel:garageUnitLabel(unit),data:result.byTank.filter(item=>item.unit===unit).map(item=>({label:item.tankName,value:item.consumption}))},
  ]).filter(chart=>chart.data.length)
  await buildExcelReport({sheetName:'حركات المخزون',companySub:'بوابة الكراج المركزي',title:identity.title,meta:`${identity.detail} · الفترة: ${result.from} إلى ${result.to} · عدد الحركات: ${result.totalCount}`,fileName:`تقرير-${identity.slug}-${result.from}-${result.to}.xlsx`,orientation:'landscape',columns:[
    {header:'#',key:'#',width:7},{header:'نوع الحركة',key:'movement',width:18},{header:'المادة',key:'fuel',width:14},{header:'الخزان',key:'tank',width:20},{header:'الآلية',key:'vehicle',width:22},{header:'DB',key:'db',width:14},{header:'القاطع والمنطقة',key:'area',width:22},{header:'الكمية',key:'quantity',width:13,numFmt:'0.000'},{header:'الوحدة',key:'unit',width:14},{header:'الرصيد قبل',key:'before',width:14,numFmt:'0.000'},{header:'الرصيد بعد',key:'after',width:14,numFmt:'0.000'},{header:'الموعد التالي',key:'next',width:16},{header:'وقت العملية',key:'created',width:22},{header:'منفذ العملية',key:'actor',width:38},{header:'ملاحظات',key:'notes',width:30,wrap:true},
  ],rows:result.rows.map(row=>({movement:movementLabels[row.movementType],fuel:fuelLabels[row.fuelType],tank:row.tankName,vehicle:row.vehicleName??'—',db:row.dbNumber??'—',area:row.areaName?`${parentSectorLabel(row.parentSector)} · ${row.areaName}`:'—',quantity:Math.abs(row.quantity),unit:garageUnitLabel(row.unit),before:row.quantityBefore,after:row.quantityAfter,next:row.fuelType==='gas_oil'?'لا ينطبق':(row.nextRefillDate??'—'),created:arDate(row.createdAt),actor:row.actorName,notes:row.notes??''})),totalRow:{movement:'ملخص حسب الوحدة',notes:unitSummary||'لا توجد حركات'},charts})
}
